    "content": "36氪获悉，中信证券研报称，近期，市场风格趋于谨慎，中药高股息标的关注度持续上升。在此背景下，中药板块凭借“低估值+高股息+成本端改善”三重属性，成为具备高确定性的细分投资板块。中信证券梳理两条投资主线：高股息率、业绩稳健标的；业绩边际向好、股息率具备一定吸引力的标的。"
