    "title": "威尼斯将2027年游客进城收费天数增至72天",
    "link": "https://36kr.com/newsflashes/4027791812891013?f=rss",
    "pub_date": "2026-10-16 08:18:37",
    "author": "",
    "description": "当地时间10月15日，意大利威尼斯市政府批准2027年游客进城费收费日历，将收费天数由2026年的60天增至72天，且每日收费时段延长半小时。根据新安排，2027年收费日期分布在3月26日至8月15日之间，主要为周五至周日及部分节假日。与2026年相比，2027年将新增8月的部分收费日期；每日收费时段由8时30分至16时调整为8时30分至16时30分。（央视新闻）",
    "content": "当地时间10月15日，意大利威尼斯市政府批准2027年游客进城费收费日历，将收费天数由2026年的60天增至72天，且每日收费时段延长半小时。根据新安排，2027年收费日期分布在3月26日至8月15日之间，主要为周五至周日及部分节假日。与2026年相比，2027年将新增8月的部分收费日期；每日收费时段由8时30分至16时调整为8时30分至16时30分。（央视新闻）"
