    "description": "临近重阳节，随着气温逐步下降，关节酸痛不适人群增多，氨基葡萄糖(以下简称“氨糖”)类保健食品迎来销售旺季。电商平台上，不少氨糖相关产品宣传中标注“修复软骨”“治疗关节炎”等功效，在买家评论区，不少消费者特别是中老年消费者将其视为保养关节的“软骨神药”。事实上，保健食品不能替代药物。",
