    "description": "",
    "content": "快科技10月16日消息，广交会现场，张雪机车创始人张雪在接受媒体采访时，聊到行业热度很高的两轮电动车自动驾驶概念，直言这件事“有点搞笑”。 采访里，张雪讲出了最核心的矛盾点，他说到：“ 两轮车它自己走的时候，前面遇到紧急状况，要刹车对不对？那我人跟着车，是配合他刹车还是不配合？我手如果没放在方向把上，就配合不了，一刹车，人直接就倒了。那自动驾驶有什么意义？ ” 紧接着他反问一句：“ 如果手已经在方向把上了，那你为什么还要自动驾驶？这不是搞笑吗？ ” 汽车可以做自动驾驶，是因为有座椅、安全带把人固定住，急刹车的时候人…"
