    "content": "快科技10月16日消息，印度马杜赖阿拉文德眼科医院的Meghana Tanwar博士团队，在国际权威眼科期刊《Ophthalmology》（《眼科学》上发表了一篇文章，里面记录的是一起极其特殊的病例。 据悉，该国一名16岁少年，遭遇了医学上极其罕见的怪事： 一颗完整的犬齿，竟然在左眼眼眶上方发育，从眼睑与眉毛之间的皮肤钻了出来 。 这名少年此前数月，左眼上眼睑一直有无痛感的肿胀，起初并没有重视，直到皮肤上冒出两处坚硬发白的凸起，他才前往马杜赖阿拉文德眼科医院就诊。 医生初步检查时，摸出肿块质地坚硬，一度怀疑是畸胎瘤…"
