    "content": "联合国粮食及农业组织（粮农组织）15日在意大利罗马宣布，中国治沙人、全国劳动模范殷玉珍入选“联合国粮农组织农业粮食体系与农村发展百位巾帼英雄”。此外，入选该名单的中国女性还有余锦秀和董敏芳。 这一全球表彰倡议由粮农组织发起，旨在纪念2026国际女农民年，表彰在农业、粮食体系和农村发展领域作出突出贡献的百位女性。 从1986年殷玉珍种下第一棵树，到如今让7万多亩沙地披上绿装，这位扎根内蒙古自治区毛乌素沙地的治沙专家用多年坚持和努力，让当地的沙漠变为绿洲。1999年，在中国任教的美国友人赛考斯（本名罗纳德·萨科尔斯基）…"
