    "content": "新华社东京10月15日电（记者陈泽安）日本有识之士15日晚在东京举行主题为“不要让日本走向新的战前状态”系列研讨会。与会人士分析高市早苗政府一系列扩军备武政策的危险性，呼吁不要让日本重蹈战争覆辙。 今年4月，高市早苗政府修改“防卫装备转移三原则”、解禁杀伤性武器出口。高市政府还计划在今年年内修订“安保三文件”。据日本媒体近日披露，高市政府可能在修订“安保三文件”时调整“无核三原则”的表述，还考虑加入探讨引进核动力潜艇相关内容。 日本山口大学名誉教授纐缬厚在研讨会上介绍了日本如何一步步松绑、解禁武器出口。他表示，虽然…"
