    "content": "前面在办公然后突然收到一条消息 如图 根据目前近 3 年的肉测，再加上同站内这条帖子 https://v2ex.com/t/1242222#reply14 基本可以证实： WeChat EU 存放位置确实不在荷兰，反正肯定不在欧洲 每次打开 WeChat 加载消息都会有数秒乃至十余秒的延迟 而 UK--DE 的延迟才 15-18ms 左右 到荷兰的延迟绝对没有这么大 查询发现数据会绕到北美--新加坡再绕地球一圈绕回来 另外根据这条消息：港澳的数据貌似一直存放在香港？（猜测）"
