    "description": "新华社德黑兰10月15日电（记者沙达提）伊朗海军15日说，其监测团队当天在霍尔木兹海峡东部海域发现一艘油轮起火。 伊朗海军当日在军队网站上发表声明说，其监测团队在对霍尔木兹海峡东部海域进行巡逻和管控时发现这艘油轮。这艘油轮关闭了追踪系统，试图穿过“禁区”。 声明说，伊朗海军部队对霍尔木兹海峡东部海域拥有“完全的控制权和主导权”。",
    "content": "新华社德黑兰10月15日电（记者沙达提）伊朗海军15日说，其监测团队当天在霍尔木兹海峡东部海域发现一艘油轮起火。 伊朗海军当日在军队网站上发表声明说，其监测团队在对霍尔木兹海峡东部海域进行巡逻和管控时发现这艘油轮。这艘油轮关闭了追踪系统，试图穿过“禁区”。 声明说，伊朗海军部队对霍尔木兹海峡东部海域拥有“完全的控制权和主导权”。"
