    "description": "联合国粮食及农业组织（粮农组织）15日在意大利罗马宣布，中国治沙人、全国劳动模范殷玉珍入选“联合国粮农组织农业粮食体系与农村发展百位巾帼英雄”。 1999年，在中国任教的美国友人赛考斯被殷玉珍扎根内蒙古毛乌素沙地治沙造林的事迹打动，筹集5000美元资助她治沙造林。 在现场见证老友收获这份荣誉后，赛考斯说，殷玉珍的故事证明了一切皆有可能。 记者：杨雅婷、高婧妍、任耀庭 报道员：莱昂纳多·隆布罗索 新华社音视频部制作",
