    "description": "15/10/2026 - 17:36 中朝新鸭绿江大桥在2014年竣工，十多年后的本周四10月15日正式开通，韩国统一研究院（KINU）朝鲜研究室主任郑恩利（Joung Eun-lee）认为这座新大桥的开通会让朝鲜更加依靠中国，请看视频报道。 中国在2014年就完成了大桥及其相关基础设施的建设，此后还投入了大量资金进行维护。朝鲜直到2019年才在其一侧修建了连接道路。如今随着这些工程完工且大桥投入使用，显而易见，朝鲜现在希望这座桥能够发…",
    "content": "15/10/2026 - 17:36 中朝新鸭绿江大桥在2014年竣工，十多年后的本周四10月15日正式开通，韩国统一研究院（KINU）朝鲜研究室主任郑恩利（Joung Eun-lee）认为这座新大桥的开通会让朝鲜更加依靠中国，请看视频报道。 中国在2014年就完成了大桥及其相关基础设施的建设，此后还投入了大量资金进行维护。朝鲜直到2019年才在其一侧修建了连接道路。如今随着这些工程完工且大桥投入使用，显而易见，朝鲜现在希望这座桥能够发挥作用。 韩国统一研究院（KINU）朝鲜研究室主任郑恩利（Joung Eun-l…"
