    "content": "新华社赫尔辛基10月15日电（记者朱昊晨 徐谦）斯德哥尔摩消息：瑞典议会15日举行投票，否决社会民主党党首、前首相玛格达莱娜·安德松出任新首相。 据瑞典电视台报道，在当天举行的投票中，安德松获得99票赞成、248票反对，未能获得议会通过。安德松曾于2021年至2022年担任瑞典首相。 安德松在投票结束后接受瑞典电视台采访时表示，瑞典议会当前面临艰难局面，可能需要经过多轮投票才能产生新政府。 瑞典议长安德烈亚斯·诺伦13日宣布提名安德松出任首相，由社会民主党单独组阁。此前，在9月议会选举中合计获得过半数席位的四个反对…"
