    "author": "wensonsmith",
    "description": "继上次把社区手机端做成了微信的样子 😆后，我又做了几个小设计，想展示一波 1.兑换码功能 经常会有送码的帖子，在帖子里粘贴一堆兑换码，然后使用人在评论区回复已使用。 但是...这真的很难一眼发现哪些还没用。 所以会有一种设计，是增加兑换码功能，把兑换码当做一个组件加到帖子中，用户点击领取获得一个兑换码。这种设计我认为首先发帖人会更麻烦，需要单独去操作这个。其次是用户领取了，但是不在评论区回复，感觉少了些热闹 因此，我在 MiddleF…",
    "content": "继上次 把社区手机端做成了微信的样子 😆 后，我又做了几个小设计，想展示一波 1.兑换码功能 经常会有送码的帖子，在帖子里粘贴一堆兑换码，然后使用人在评论区回复已使用。 但是...这真的很难一眼发现哪些还没用。 所以会有一种设计，是增加兑换码功能，把兑换码当做一个组件加到帖子中，用户点击领取获得一个兑换码。这种设计我认为首先发帖人会更麻烦，需要单独去操作这个。其次是用户领取了，但是不在评论区回复，感觉少了些热闹 因此，我在 MiddleFun 社区 的设计是，自动从回复中读取用过的码，把帖子详情中的码自动划掉。 …"
