    "content": "新华社巴库10月15日电（记者钟忠 刘书辰）习近平主席特别代表、中共中央政治局委员、外交部长王毅15日在巴库出席亚洲相互协作与信任措施会议第七次峰会，就推进亚信成员国合作提出四点倡议。 一是共同维护和平稳定。亚洲不需要冷战思维，不欢迎阵营对抗。亚洲的问题归根结底要靠亚洲人民通过团结协作来处理，亚洲的安全归根结底要靠坚持共同、综合、合作、可持续的安全观来解决。 中东局势复杂演变，世界深受影响。中方鼓励美国和伊朗重新回归政治外交轨道化解争端，呼吁也门问题当事方保持克制。地区国家的主权和安全应当受到尊重，国际产业链供应链…"
