    "content": "新华社巴库10月15日电（记者钟忠 刘书辰）习近平主席特别代表、中共中央政治局委员、外交部长王毅15日在巴库出席亚洲相互协作与信任措施会议第七次峰会并发表讲话。 王毅表示，亚信是亚洲国家自主发起、携手共建的全亚洲对话合作平台。自成立以来，积极倡导和平共处五项原则，系统推进信任措施合作，始终践行多边主义，锲而不舍夯筑亚洲和平与安全的信任基础。中方高度评价阿塞拜疆担任主席国期间为推动亚信合作、建设“更强的亚洲”所作努力，愿继续大力支持和积极参与亚信进程。 王毅说，亚洲生活着全球60%的人口，在世界历史长河中引领过世界发…"
