    "content": "新华社雅加达10月15日电（记者李斯博）为期三天的第七届“一带一路”税收征管合作论坛15日在印度尼西亚雅加达闭幕。论坛达成广泛共识，取得六项重要成果。 论坛期间，中国国家税务总局副局长蔡自力围绕“强化数智赋能 提升征管效能”发表主旨演讲。他表示，当前数字经济和人工智能技术飞速发展，给各国税收治理带来新的挑战。中国税务部门面对“涉税经营主体多、经济业态模式新、税务数据来源广、技术应用迭代快”的形势与挑战，从培训对象、知识体系、课程资源、教学方式、效果转化等五个维度深耕发力，全方位构建数智能力提升培训体系。 印度尼西亚…"
