    "content": "新华社澳门10月15日电（记者宋晨、齐菲）“澳门学论坛2026”15日在澳门科技大学举行，本届论坛以“孙中山与澳门”为主题，纪念孙中山先生诞辰160周年，缅怀先生丰功伟绩，传承和弘扬中山精神。 中国社会科学院学部委员、中国历史研究院澳门历史研究中心主任李国强通过视频致辞表示，此次论坛是缅怀革命先驱、赓续爱国主义传统、奋力实现民族复兴的有力践行。孙中山先生与澳门渊源深厚，与家人在澳门留下了弥足珍贵的历史足迹。中国历史研究院高度重视澳门历史文化研究，与澳门科技大学合作共建澳门历史研究中心，积极构建“一国两制”基础理论和…"
