    "description": "新华社伦敦10月15日电（记者于艾岑）英国政府15日宣布，将拨款1700万英镑（约合2254万美元），用于支持切尔诺贝利核电站的维修工作，以恢复核电站建筑的封闭和通风功能。 据英国财政部和外交部当日发布的消息，该笔款项将支持由欧洲复兴开发银行协调的一项国际计划，用于相关维修工作。 去年2月，切尔诺贝利核电站一个用于封存反应堆的保护罩因遭无人机袭击受损，失去密封性能。事件发生后，乌克兰称该无人机来自俄罗斯，但俄罗斯予以否认。 切尔诺贝利核…",
    "content": "新华社伦敦10月15日电（记者于艾岑）英国政府15日宣布，将拨款1700万英镑（约合2254万美元），用于支持切尔诺贝利核电站的维修工作，以恢复核电站建筑的封闭和通风功能。 据英国财政部和外交部当日发布的消息，该笔款项将支持由欧洲复兴开发银行协调的一项国际计划，用于相关维修工作。 去年2月，切尔诺贝利核电站一个用于封存反应堆的保护罩因遭无人机袭击受损，失去密封性能。事件发生后，乌克兰称该无人机来自俄罗斯，但俄罗斯予以否认。 切尔诺贝利核电站位于乌克兰首都基辅以北约110公里处。1986年，核电站4号反应堆爆炸，造成…"
