    "content": "美国友人赛考斯（本名罗纳德·萨科尔斯基）日前在意大利罗马接受记者采访时说，他希望以他与殷玉珍的故事搭起一座桥梁，让更多人跨越国界、携手守护共同的地球家园。 1999年，在中国任教的赛考斯被殷玉珍扎根内蒙古毛乌素沙地治沙造林的事迹打动，筹集5000美元资助她治沙造林。赛考斯回国后，两人一度失去联系。今年8月，他们在中国重逢。当年购买的5万多棵树苗，如今也已长成林木。 10月15日，在殷玉珍入选“联合国粮农组织农业粮食体系与农村发展百位巾帼英雄”的活动现场，赛考斯见证了老友收获这份荣誉。 记者：杨雅婷、高婧妍、任耀庭、…"
