    "description": "新华社乌兰巴托10月15日电（记者哈丽娜）援蒙古国中蒙元首体育中心项目奠基仪式15日在蒙古国首都乌兰巴托市举行。 蒙古国总统呼日勒苏赫在仪式致辞中说，该项目是两国友好关系与合作的生动体现，将助力蒙古国体育事业发展，为民众参与体育锻炼、践行健康生活方式创造良好条件。 中国驻蒙古国大使馆临时代办曹利表示，中蒙是山水相连的友好邻邦，也是高质量共建“一带一路”的合作伙伴。该项目是中蒙友好合作又一标志性工程。 援蒙古国中蒙元首体育中心项目由陕西建…",
