    "content": "新华社杜尚别10月15日电 通讯｜中塔货运班列跑出互联互通“加速度” 新华社记者胡伟杰 安晓萌 姚子云 随着汽笛声响起，一列从中国甘肃武威发车的货运班列缓缓驶入塔吉克斯坦苦盏站。自今年2月该货运线路开通以来，这是抵达苦盏站的第21趟班列，运载着当地经销商采购的商用空调零件。 苦盏站所在的苦盏市位于费尔干纳盆地，是塔吉克斯坦第二大城市。苦盏站站长奥比多夫虽然从未去过武威，但他亲眼看到，通过开通的铁路货运通道，越来越多中国商品经武威运抵塔吉克斯坦，满足当地民生和基础设施建设需求。 近年来，中塔经贸往来日益密切，两国物流…"
