    "pub_date": "2026-10-15 22:46:33",
    "author": "王作葵",
    "description": "新华社莫斯科10月15日电（记者王作葵）俄罗斯总统新闻秘书佩斯科夫15日表示，欧洲对于俄美之间达成的柴油供应协议持“破坏性立场”。 佩斯科夫在当天举行的新闻发布会上说，欧洲国家不仅没有欢迎这一协议，还提出严厉批评。此外，过去几天，乌克兰针对俄罗斯炼油厂和其他能源设施的袭击仍在继续，没有任何暂停的迹象。 他还说，当前包括石油市场在内的全球能源市场处于非常紧张的状态。造成这一局面的因素很多，俄罗斯大量石油和石油产品出口受限是原因之一。俄罗斯…",
    "content": "新华社莫斯科10月15日电（记者王作葵）俄罗斯总统新闻秘书佩斯科夫15日表示，欧洲对于俄美之间达成的柴油供应协议持“破坏性立场”。 佩斯科夫在当天举行的新闻发布会上说，欧洲国家不仅没有欢迎这一协议，还提出严厉批评。此外，过去几天，乌克兰针对俄罗斯炼油厂和其他能源设施的袭击仍在继续，没有任何暂停的迹象。 他还说，当前包括石油市场在内的全球能源市场处于非常紧张的状态。造成这一局面的因素很多，俄罗斯大量石油和石油产品出口受限是原因之一。俄罗斯柴油已开始进入国际市场，将对稳定石油市场起到积极作用，但无法完全使市场恢复稳定。…"
