    "content": "我平时用网易 UU 远程控制家里的电脑，但电脑完全关机时还需要局域网内有个常在线设备帮忙唤醒。之前用旧安卓手机做辅助设备，后来想让路由器承担这件事，于是把几次真实路由器的实验整理成一个开源工具。 项目是第三方社区脚本， 不是网易官方插件 ，不分发网易闭源二进制。主要做四件事： 自动识别路由器固件和处理器架构，匹配已知平台；未知型号默认只检测，不擅自安装。 从网易官方接口获取并校验插件，在可验证的环境引导启动、配置辅助设备。 对可安装的平台提供受控持久服务、健康检查、安全停止和回滚；避免为了远程开机破坏路由器现有设置…"
