    "pub_date": "2026-10-15 22:28:41",
    "author": "",
    "description": "大家好！我是一名来自西班牙的独立开发者。这周我的第一款游戏《轨道：宾果肉鸽》在 Steam 上线了。它有原生 Linux 版（不用走 Proton），而且从头到尾都是在 CachyOS（基于 Arch）上开发的，所以想来这里分享一下。先说清楚：这是一款付费的商业游戏，不开源，发帖的是开发者本人。 游戏是我一个人做的（有几位测试者帮忙），上线比较冷清：到现在卖出 26 份，收到 5 篇评测，都是好评，我反复看了好多遍。 玩法 这是一款在宾…",
    "content": "大家好！我是一名来自西班牙的独立开发者。这周我的第一款游戏《轨道：宾果肉鸽》在 Steam 上线了。它有原生 Linux 版（不用走 Proton），而且从头到尾都是在 CachyOS（基于 Arch）上开发的，所以想来这里分享一下。先说清楚：这是一款付费的商业游戏，不开源，发帖的是开发者本人。 游戏是我一个人做的（有几位测试者帮忙），上线比较冷清：到现在卖出 26 份，收到 5 篇评测，都是好评，我反复看了好多遍。 玩法 这是一款在宾果卡上进行的回合制策略 Roguelite。不用等待叫号，而是自己从托盘里挑球。…"
